// User recordings: 1–3 are nearby/chase calls; 4 is reserved for capture.
export const PIG_AUDIO_URLS=[1,2,3,4].map(n=>new URL(`./assets/audio/pig-${n}.mp3`,import.meta.url).href);
export function preloadPigAudio(fetcher=fetch){return Promise.all(PIG_AUDIO_URLS.map(async url=>{try{const r=await fetcher(url);if(!r.ok)throw new Error(`Audio HTTP ${r.status}`);return await r.arrayBuffer();}catch(e){console.warn('Pig recording unavailable:',url,e);return null;}}));}
export class PigAudio{
 constructor(context,destination,data){this.context=context;this.destination=destination;this.buffers=[];this.voice=null;this.epoch=0;this.nextAt=0;this.nextVariation=0;this.ready=data.then(async bytes=>{this.buffers=await Promise.all(bytes.map(async b=>{try{return b?await context.decodeAudioData(b.slice(0)):null;}catch(e){console.warn('Pig recording decode failed',e);return null;}}));});}
 stop(){this.epoch++;if(this.voice){this.voice.source.stop();this.voice=null;}this.nextAt=this.context.currentTime+2;}
 play(index,volume,pan=0){const buffer=this.buffers[index];if(!buffer)return false;const source=this.context.createBufferSource(),gain=this.context.createGain();source.buffer=buffer;gain.gain.value=volume;source.connect(gain);let panner=this.context.createStereoPanner?.();if(panner){panner.pan.value=pan;gain.connect(panner);panner.connect(this.destination);}else gain.connect(this.destination);const voice={source,gain,panner,index};this.voice=voice;source.onended=()=>{source.disconnect();gain.disconnect();panner?.disconnect();if(this.voice===voice)this.voice=null;};source.start();this.nextAt=this.context.currentTime+buffer.duration+3+Math.random()*3;return true;}
 update({chasing,distance,pan=0}){const nearby=distance<8,volume=nearby?Math.max(.035,(1-distance/9)*(chasing?.48:.3)):0;if(this.voice){if(this.voice.index===3)return;this.voice.gain.gain.setTargetAtTime(volume,this.context.currentTime,.25);if(this.voice.panner)this.voice.panner.pan.setTargetAtTime(pan,this.context.currentTime,.15);return;}if(!nearby||this.context.currentTime<this.nextAt)return;for(let i=0;i<3;i++){const index=this.nextVariation;this.nextVariation=(index+1)%3;if(this.play(index,volume,pan))break;}}
 async caught(quiet=false){this.stop();const epoch=this.epoch;await this.ready;if(epoch!==this.epoch)return;this.play(3,quiet?.2:.65,0);}
}
